(function(root){
  const object=x=>x&&typeof x==='object'&&!Array.isArray(x);
  const text=x=>typeof x==='string'?x:x==null?'':JSON.stringify(x);
  function list(value,name){if(value===undefined)return undefined;if(!Array.isArray(value))throw Error(name+' 必须是数组');return value;}
  function duration(v){if(v===undefined||v===null||v==='')return null;const n=Number(v);if(!Number.isFinite(n)||n<=0)throw Error('镜头时长必须是正数或留空，不限制为 5 秒');return n;}
  function character(c,i){if(typeof c==='string')c={name:c};if(!object(c))throw Error('角色 '+(i+1)+' 格式错误');return{...c,id:c.id||c.character_id||'character_'+String(i+1).padStart(2,'0'),name:text(c.name||c.character_name||'新角色'),role:text(c.role||c.story_role||c.identity||'配角'),description:text(c.description||c.appearance||c.personality||c.character_arc),prompt:text(c.prompt||c.front_prompt||c.prompts?.front||c.generation?.positive_prompt||c.prompt_anchor_zh),negativePrompt:text(c.negativePrompt||c.negative_prompt||c.generation?.negative_prompt||(Array.isArray(c.negative_constraints)?c.negative_constraints.join("\n"):c.negative_constraints)),multiPrompt:text(c.multiPrompt||c.multiview_prompt||c.prompts?.multiview||CharacterSheet.spec.prompt),versions:Array.isArray(c.versions)?c.versions:[],multi:Array.isArray(c.multi)?c.multi:[],confirmed:c.confirmed===true};}
  function shot(s,i){if(typeof s==='string')s={title:s};if(!object(s))throw Error('分镜 '+(i+1)+' 格式错误');return{...s,id:s.id||s.shot_id||'shot_'+String(i+1).padStart(2,'0'),title:text(s.title||s.name||'镜头 '+(i+1)),description:text(s.description||s.visual||s.action),prompt:text(s.prompt||s.image_prompt||s.prompts?.image),duration:duration(s.duration??s.duration_seconds??s.seconds),versions:Array.isArray(s.versions)?s.versions:[]};}
  function parse(input){if(!object(input))throw Error('JSON 顶层需要是对象');let kind=input.type||input.module||((input.schema_type==='character_library'||input.file_type==='character_bible')?'characters':'project');if(!['project','outline','characters','storyboard'].includes(kind))throw Error('type 支持 project、outline、characters、storyboard');let p=object(input.project)?input.project:input;let outline=object(input.outline)?input.outline:p;let chars=list(input.characters??p.characters??input.roles??p.roles??input.story?.main_characters??p.story?.main_characters,'characters'),shots=list(input.shots??p.shots??input.storyboards??p.storyboards,'shots');if(kind==='characters'&&!chars)throw Error('人物模块缺少 characters 数组');if(kind==='storyboard'&&!shots)throw Error('分镜模块缺少 shots 数组');let mapped={...p,...(object(input.outline)?input.outline:{})};for(let k of ['characters','shots','roles','storyboards','project','outline','type','module'])delete mapped[k];if(kind==='project'||kind==='outline'){mapped.title=text(outline.title||outline.name||p.title||'未命名短剧');mapped.synopsis=text(outline.synopsis||outline.story?.synopsis||outline.story?.logline||outline.story_summary||outline.summary||outline.description);if(outline.basic_info?.genre)mapped.genre=Array.isArray(outline.basic_info.genre)?outline.basic_info.genre.join(' / '):text(outline.basic_info.genre);if(outline.creative_vision?.visual_style?.type)mapped.style=text(outline.creative_vision.visual_style.type);if(outline.production_targets?.aspect_ratio)mapped.ratio=text(outline.production_targets.aspect_ratio);if(outline.production_targets?.target_duration_seconds||outline.basic_info?.target_duration_seconds)mapped.target_duration_seconds=outline.production_targets?.target_duration_seconds||outline.basic_info.target_duration_seconds;if(outline.basic_info?.language)mapped.language=outline.basic_info.language;if(outline.story_prompt!==undefined)mapped.storyPrompt=text(outline.story_prompt)}return{kind,projectId:input.project_id||p.project_id||'',meta:mapped,characters:chars?.map(character),shots:shots?.map(shot)};}
  function apply(current,input,defaults){let parsed=parse(input);if(parsed.kind!=='project'&&parsed.projectId&&current.project_id&&parsed.projectId!==current.project_id)throw Error('project_id 与当前项目不同，请先导入对应总纲或整包项目');let next=parsed.kind==='project'?{...defaults,...parsed.meta,characters:[],shots:[],stages:parsed.meta.stages||{}}:{...current};if(parsed.kind==='project'||parsed.kind==='outline')next={...next,...parsed.meta};if(parsed.projectId)next.project_id=parsed.projectId;if(parsed.characters!==undefined)next.characters=parsed.characters;if(parsed.shots!==undefined)next.shots=parsed.shots;if(parsed.kind==='characters'){for(const field of ['relationships','global_consistency'])if(parsed.meta[field]!==undefined)next[field]=parsed.meta[field];next.character_library_version=parsed.meta.version||next.character_library_version;}next.schema_version='2.0';return{data:next,kind:parsed.kind};}
  function pack(data,kind='project'){let meta={...data};for(let k of ['characters','shots','stages','type','schema_version'])delete meta[k];let result={schema_version:'2.0',type:kind,project_id:data.project_id||'',};if(kind==='project'||kind==='outline')result.outline=meta;if(kind==='project'||kind==='characters')result.characters=data.characters;if(kind==='project'||kind==='storyboard')result.shots=data.shots.map((s,i)=>shot(s,i));if(kind==='project')result.stages=data.stages||{};return result;}
  const api={parse,apply,pack,duration};if(typeof module!=='undefined')module.exports=api;else root.FrameJSON=api;
})(typeof window!=='undefined'?window:globalThis);
